<script setup>
const INVITE = "https://discord.gg/gorillatagcomp";
const { data, refresh, error: billingError } = await useApiFetch("/api/billing/config", { key: "billing-config-settings", default: () => null });
const { data: mine, refresh: refreshMine } = await useApiFetch("/api/me/player", { key: "settings-player", default: () => ({ player: null }) });
const { me, load } = useMe();
const config = computed(() => data.value);
const signedIn = computed(() => Boolean(me.value.user));
const tiers = computed(() => config.value?.catalog?.tiers || []);
const plan = computed(() => config.value?.plan?.plan || "free");
const planName = computed(() => plan.value === "free" ? "Free" : "Ranked World " + plan.value[0].toUpperCase() + plan.value.slice(1));
const linked = computed(() => mine.value?.player || null);
const { toast } = useToast();
const unlinking = ref(false);
const confirmUnlink = ref(false);
async function unlink() { if (!confirmUnlink.value) { confirmUnlink.value = true; setTimeout(() => confirmUnlink.value = false, 5000); return; } confirmUnlink.value = false; unlinking.value = true; try { await apiFetch("/api/me/link", { method: "DELETE" }); await refreshMine(); toast("Gorilla Tag account disconnected."); } catch (e) { toast(e?.data?.statusMessage || e?.message || "That did not go through."); } finally { unlinking.value = false; } }
const ELSEWHERE = [{ icon: "bell", label: "Notification preferences", hint: "Bot commands, for now", href: INVITE }, { icon: "book", label: "Rules and conduct", hint: "What gets you rank banned", href: INVITE }, { icon: "shield", label: "Appeal a ban", hint: "Open a ticket in the server", href: INVITE }, { icon: "inbox", label: "Support", hint: "Anything else, ask in Discord", href: INVITE }];
onMounted(() => load());
useHead({ title: "Settings | Ranked World" });
const signingOut = ref(false);
const signingOutAll = ref(false);
const confirmAll = ref(false);
async function signOutEverywhere() { if (!confirmAll.value) { confirmAll.value = true; setTimeout(() => confirmAll.value = false, 5000); return; } confirmAll.value = false; signingOutAll.value = true; try { await apiFetch('/api/me/sessions', { method: 'POST', body: { action: 'logout-everywhere' } }); await apiFetch('/auth/logout', { method: 'POST' }).catch(() => {}); window.location.assign('/'); } catch { toast('Could not sign out everywhere. Try again.'); signingOutAll.value = false; } }
async function signOut() { signingOut.value = true; try { await apiFetch('/auth/logout', { method: 'POST' }); window.location.assign('/'); } catch { toast('Could not sign out. Try again.'); signingOut.value = false; } }
</script>
<template>
<main id="main" class="wrap section"><div class="world-page-title"><div><h1>Settings</h1></div></div><div class="world-settings-layout"><nav class="world-settings-nav" aria-label="Account sections"><a href="#identity">Connected accounts</a><a href="#membership">Membership</a><a v-if="signedIn" href="#replay-permission">Replay permission</a><a href="#support">Help and community</a><NuxtLink to="/me">Your player profile</NuxtLink><NuxtLink to="/history">Match history</NuxtLink><NuxtLink to="/leaderboard?sort=friends">Friends leaderboard</NuxtLink><NuxtLink to="/notifications">Notifications</NuxtLink><NuxtLink to="/launcher">Launcher</NuxtLink><NuxtLink to="/ranked">How ranking works</NuxtLink></nav><div><section id="identity" class="world-settings-section"><h2>Connected accounts</h2><div class="world-setting-row"><AppIcon name="discord" /><div><h3>Discord</h3><p class="meta">{{ me.user?.username || 'Sign in to manage your account.' }}</p></div><span v-if="signedIn" class="chip chip--live">Connected</span><a v-else class="btn btn--brand" href="/sign-in">Sign in</a></div><div class="world-setting-row"><AppIcon name="link" /><div><h3>Gorilla Tag</h3><p class="meta">{{ linked?.linked ? linked.name : 'Not connected' }}</p><PhotonId v-if="linked?.photonId" :id="linked.photonId" /></div><button v-if="linked?.linked" class="btn" :disabled="unlinking" @click="unlink">{{ unlinking ? 'Disconnecting...' : confirmUnlink ? 'Confirm disconnect' : 'Disconnect' }}</button><NuxtLink v-else class="btn" to="/play">Connect</NuxtLink></div><p v-if="confirmUnlink" class="meta" role="status">Disconnecting removes your account connection. It does not delete stored records or cancel billing. Press Confirm disconnect to continue.</p></section><section id="membership" class="world-settings-section"><h2>Membership</h2><div v-if="billingError" class="world-error" role="alert"><p>Could not load your membership.</p><button class="btn" @click="refresh">Try again</button></div><template v-else><div class="world-setting-row"><AppIcon name="sparkles" /><div><h3>{{ planName }}</h3></div><NuxtLink class="btn" to="/subscribe">{{ plan === 'free' ? 'Explore plans' : 'View plans' }}</NuxtLink></div><PlusManageSubscription v-if="signedIn && plan !== 'free'" :plan="config?.plan" :tiers="tiers" @changed="refresh()" /></template></section><section v-if="signedIn" id="replay-permission" class="world-settings-section"><ReplayConsentGate settings /></section><section class="world-settings-section"><h2>Privacy requests</h2><p>Request a copy, correction, or deletion of your data by email. Disconnecting does not erase stored records.</p><a class="btn" href="mailto:contact@rankedworld.com?subject=Privacy%20request">Email a privacy request</a><NuxtLink class="btn btn--ghost" to="/legal/privacy">Read Privacy policy</NuxtLink></section><section id="support" class="world-settings-section"><h2>Help and community</h2><p class="meta">Our Discord team handles support, rules, and appeals.</p><a v-for="e in ELSEWHERE" :key="e.label" class="world-setting-row" :href="e.href"><AppIcon :name="e.icon" /><div><h3>{{ e.label }}</h3><p class="meta">{{ e.hint }}</p></div><AppIcon name="external" /></a></section><button v-if="signedIn" class="btn" :disabled="signingOut" @click="signOut"><AppIcon name="logOut" />{{ signingOut ? 'Signing out...' : 'Sign out' }}</button><button v-if="signedIn" class="btn" :disabled="signingOutAll" @click="signOutEverywhere"><AppIcon name="shield" />{{ signingOutAll ? 'Signing out...' : confirmAll ? 'Confirm sign out everywhere' : 'Sign out everywhere' }}</button><p v-if="confirmAll" class="meta" role="status">This signs out every browser and every installed launcher on your account. Press Confirm to continue.</p></div></div></main>
</template>
